    s.left = [{ uid: "l1", id: 5, date: today, type: "dish" }]; s.fav = [5, 12]; s.rating = { 5: 8 }; s.notes = { 5: MK.note }; s.cols[0].ids = [5]; s.hist = { 5: [{ r: 4, d: today, u: "h1" }] }; s.ver = {}; s.inv = { rice: { exp: today } }; s.invTx = {}; s.photos = {};
