    await T("crypto", "AES-GCM: changed ciphertext or changed header is rejected", async () => { const k = await RC.aesKey(RC.rand(32)), b = await RC.seal(k, "hello", "A"); const ct = RC.unb64(b.ct); ct[0] ^= 1; return [await throwsCode(() => RC.open(k, { n: b.n, ct: RC.b64(ct) }, "A")) && await throwsCode(() => RC.open(k, b, "B")) && RC.td.decode(await RC.open(k, b, "A")) === "hello"]; });
    await T("crypto", "a household code gives the same household id and key on both phones; another code does not", async () => { const c = RC.rand(16), a = await HouseShare.keysFor(c), b = await HouseShare.keysFor(RC.u8([...c])), x = await HouseShare.keysFor(RC.rand(16)); const box = await RC.seal(a.hk, "t", "x"); return [a.hh === b.hh && a.hh !== x.hh && RC.td.decode(await RC.open(b.hk, box, "x")) === "t" && await throwsCode(() => RC.open(x.hk, box, "x"))]; });
